// TH18 v1.00a Extra, stage07 boss nonspell 15 (st07bs.ecl.txt::Boss8:757-816).
// Source closure actually used: Boss8 -> Boss7_at:730-755 twice.  Boss8_at is
// not called by this segment and is deliberately absent.
//
// Source -> card frame relation:
//   phase t=0 is the card opening; the real boss is spawned after OPENING_BUFFER
//   (t~=120).  Source Boss8's 120-frame move/limit wait and 60-frame pre-fire
//   wait are kept inside the boss task, so the first wave is at boss entry+181.
//   The source activity-slot timer is 4200 frames (setInterrupt(0,3500,4200)).
//   TIME_LIMIT=4380 = 120 buffer + 4200 source timer + 60 tail.  The next card
//   (BossCard8) is not executed.

const TIME_LIMIT: int = 4380;
const OPENING_BUFFER: int = 120;

// TH18 etSprite(12,14) -> type12 ARROWHEAD, color 14 (bullet-types.md).
const TH18_ARROWHEAD: int = 544;
const ARROWHEAD_COLOR: int = 14;

// Boss8 body: source Boss entry setHitbox(48,48)/setHurtbox(40,40) -> r24/r20.
const BOSS_HITBOX: fx = 24fx;
const BOSS_HURTBOX: fx = 20fx;

// Boss7_at arguments, converted from radians to BAM.
//   D = +/-0.15707964 rad = +/-9deg   (ring base turns once per 10-frame wave)
//   F = -/+0.11519173 rad = -/+6.6deg (per-layer angular offset; 1201 BAM)
const WAVE_BASE_STEP: angle = 9deg;
const LAYER_STEP_BAM: int = 1201;
const RING_HALF_STEP_BAM: int = 6554; // pi/N for N=5 = 36deg

// Source EX chain on every Boss7_at bullet:
//   type 0x200000 VELTIME, a=60, r=3.0, s=-9999994 (angle retained)
//   type 0x8 ANGLE_ACCEL, a=30, r=-0.01, s=0.0
// async=0 makes the second effect wait for the first; the birth ANIM record
// (type2, a=1) is omitted per the approved birth-phase omission, while its
// position -= 4*velocity displacement is applied to the spawn point below.
xformdef BOSS7_BULLET {
    step_speed(3fx, 60 + 65536 * EASE_LINEAR);
    wait(60);
    set_ang_vel(0deg);
    set_accel(-0.01fx);
    wait(30);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// ---------------------------------------------------------------------------
// Boss7_at (st07bs.ecl.txt:730-755): the two async copies rotate the fixed
// five-way ring in opposite directions, with opposite per-layer offsets.
// Native loop order is layer q outside, way i inside; the explicit fire()
// loops below keep that order and the per-layer spawn distance.
// The source's slot-0 interrupt cuts the loop at 4200 frames from Boss8 entry;
// the first wave is at entry+181 and the period is 10 frames, so waves
// 0..401 (last at entry+4191) run and the 60-frame phase tail adds no new
// wave.  The 402-wave bound stands in for that source interrupt.
const MAX_WAVES: int = 402;
async sub boss7_at(base_step: angle, layer_step_bam: int) {
    var g: angle = aim_player(); // source: %G = %ANGLE_PLAYER at entry
    var waves: int = 0;
    loop {
        for q in 0..7 {
            // etSpeed(1.2, 0.0) with 7 layers: 1.2,1.0,...,0.0.
            var v: fx = (6 - q) as fx * 0.2fx;
            // etDist(32) combined with ANIM position -= 4*velocity.
            var dist: fx = 32fx - 4fx * v;
            for i in 0..5 {
                // etAim(5): alpha + pi/N + R(i) + q*delta, N=5.
                var a: int = (g as int) + RING_HALF_STEP_BAM
                    + (i * 65536) / 5 + q * layer_step_bam;
                // etOffset(0,-24) from the enemy FINAL, then etDist along a.
                var bx: fx = $self_x + dist * cos(a as angle);
                var by: fx = $self_y - 24fx + dist * sin(a as angle);
                _ = fire(TH18_ARROWHEAD, ARROWHEAD_COLOR, bx, by,
                         v, a as angle, BOSS7_BULLET, none);
            }
        }
        waves = waves + 1;
        if waves >= MAX_WAVES { break; }
        // etAngle(A, %G, %F); %G = %G + %D; etOn(A); wait(10).
        g = g + base_step;
        wait(10);
    }
}

// ---------------------------------------------------------------------------
// Boss8 movement loop, source Boss8_1320/Boss8_1456.
// moveRand(60,4,1.0) over moveLimit(0,128,240,64), validated recipe from
// movement.md with this card's limit: x in [-120,120], y in [96,160]; the
// inner direction region is x +-60, y 112..144.
// ---------------------------------------------------------------------------
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    // 412 moveRand(60,4,1.0): one signed direction sample at the call position.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// ---------------------------------------------------------------------------
// Real boss: source Boss8 entry settings, then the 120+60 opening waits, then
// the two Boss7_at async calls, then the movement loop.
// ---------------------------------------------------------------------------
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(BOSS_HITBOX);
    set_hurtbox(BOSS_HURTBOX);

    // Source entry also cancels the previous card's bullets and motion; the
    // independent card starts clean and stationary at (0,128), so those
    // boundary hand-offs are omitted. movePosTime(60,4,0,128) is a no-op from
    // the prescribed (0,128) start.
    wait(120);   // moveLimit(0,128,240,64) is enforced by the movement helper.
    wait(60);    // source waits 60 before the two async calls.

    spawn boss7_at(WAVE_BASE_STEP, -LAYER_STEP_BAM);
    spawn boss7_at(-WAVE_BASE_STEP, LAYER_STEP_BAM);

    // Boss8_1456 -> Boss8_1320.  The two moveRand calls are 160 frames apart.
    loop {
        wait(100);
        move_rand();
        move_wait(60);
        wait(100);
        move_rand();
        move_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18500, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Segment boundary: the real boss was created by the pattern task, so stop
    // it here instead of letting it keep firing after the phase timeout (the
    // source hands this cleanup to the next card's Boss8 entry).
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
